window.closeWorkoutInspector=()=>{workoutUi.selected=null;workoutUi.collapsed=false;renderWorkouts();};
if(!window._workoutDismissListeners){window._workoutDismissListeners=true;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&workoutUi.selected&&activeSection==='activity'&&activeSubtab==='workouts')window.closeWorkoutInspector();});document.addEventListener('click',e=>{if(!workoutUi.selected||activeSection!=='activity'||activeSubtab!=='workouts')return;const t=e.target;if(t.closest('#workoutInspectorShell')||t.closest('[data-workout-row]')||t.closest('[data-workout-id]')||t.closest('[data-wtype]')||t.closest('#workouts .workout-toolbar')||t.closest('#workouts .workout-controls')||t.closest('#workouts .workout-table-wrap')||t.closest('#workouts .workout-chip')||t.closest('#workoutCalendarMetric')||t.closest('button,select,input,textarea,a,summary,details,[role=button]'))return;if(t.closest('.app-shell'))window.closeWorkoutInspector();});}
window.pickWorkout=(id,scroll=true)=>{workoutUi.selected=id;renderWorkouts();if(scroll)document.querySelector('#workoutInspector')?.scrollIntoView({behavior:'auto',block:'start'});};
window.filterWorkoutBucket=(key,gran)=>{workoutUi.range='all';workoutUi.type='ALL';workoutUi.hideShort=false;const end=gran==='day'?localDateKey(dayMs(key)+DAY):gran==='week'?localDateKey(dayMs(key)+7*DAY):(()=>{const d=new Date(key+'T12:00:00');d.setMonth(d.getMonth()+1);return localDateKey(new Date(d.getFullYear(),d.getMonth(),1));})();const pick=workoutDataAllSorted().find(w=>w.day>=key&&w.day<end);if(pick)workoutUi.selected=pick.id;renderWorkouts();const table=$('#workouts .workout-table tbody');if(table)[...table.rows].forEach(r=>r.hidden=!(r.cells[0]?.textContent>=key&&r.cells[0]?.textContent<end));};window.filterWorkoutWeek=(week)=>window.filterWorkoutBucket(week,'week');
window.filterWorkoutDay=(day)=>{workoutUi.range='all';workoutUi.type='ALL';workoutUi.hideShort=false;const pick=workoutDataAllSorted().find(w=>w.day===day);if(pick)workoutUi.selected=pick.id;renderWorkouts();const table=$('#workouts .workout-table tbody');if(table)[...table.rows].forEach(r=>r.hidden=!r.cells[0]?.textContent.includes(day));document.querySelector('#workoutInspector')?.scrollIntoView({behavior:'auto',block:'start'});};

function renderHeatmap(){
  const host = $('#heatmap'); if(!host) return;
  const workouts = activeWorkouts();
  const loadByDay = {}, durationByDay = {};
  for(const e of workouts){
    const sMs = new Date(e.start).getTime();
    const eMs = new Date(e.end).getTime();
    const durationS = Number(e.duration_s);
    const mins = Number.isFinite(durationS) && durationS > 0 ? durationS/60 : ((Number.isFinite(sMs) && Number.isFinite(eMs) && eMs >= sMs) ? (eMs-sMs)/60000 : 0);
    const rawKcal=e.kcal ?? e.calories_kcal;
    const kcal=Number.isFinite(Number(rawKcal)) && Number(rawKcal)>0 ? Number(rawKcal) : 1;
    if(mins>0 && mins<24*60 && e.day){durationByDay[e.day]=(durationByDay[e.day]||0)+mins;loadByDay[e.day]=(loadByDay[e.day]||0)+mins*kcal;}
  }
  const today = new Date(); today.setHours(0,0,0,0);
  const selectedDays = Number.isFinite(Number(days)) ? Math.max(7, Math.min(3650, Number(days))) : 365;
  const start = new Date(today.getTime() - selectedDays * DAY);
  const dow = (start.getDay() + 6) % 7;
  start.setDate(start.getDate() - dow);
  const weeks = [];
  let cur = new Date(start);
  const maxLoad = Math.max(1, ...Object.values(loadByDay));
  const shades = [
    {thr: 0,    c: 'var(--wash)'},
    {thr: 0.20, c: 'rgba(74,222,128,.25)'},
    {thr: 0.40, c: 'rgba(74,222,128,.45)'},
    {thr: 0.65, c: 'rgba(74,222,128,.70)'},
    {thr: 0.85, c: 'rgba(74,222,128,1)'},
  ];
  const colorFor = (load) => {
    if(!load) return shades[0].c;
    const r = load / maxLoad;
    for(let i=shades.length-1;i>=0;i--) if(r >= shades[i].thr) return shades[i].c;
    return shades[1].c;
  };
  const dayKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  while(cur <= today){
    const col = [];
    for(let i=0;i<7;i++){
      const d = new Date(cur);
      const key = dayKey(d);
      const mins = durationByDay[key] || 0, load = loadByDay[key] || 0;
      const inRange = d <= today;
      const title = inRange ? `${d.toLocaleDateString([], {weekday:'short', month:'short', day:'numeric', year:'numeric'})}: ${Math.round(mins)} min · ${Math.round(load).toLocaleString()} min×kcal` : '';
      col.push(`<div class="hm-cell ${inRange?'':'empty'}" style="background:${inRange?colorFor(load):'transparent'}" title="${title}"></div>`);
      cur.setDate(cur.getDate() + 1);
    }
    weeks.push(`<div class="hm-col">${col.join('')}</div>`);
  }
  const monthLabels = weeks.map((_,wi)=>{
    const d = new Date(start);
    d.setDate(d.getDate() + wi*7);
    if(d.getDate() <= 7) return `<span class="hm-label">${d.toLocaleDateString([], {month:'short'})}</span>`;
    return `<span class="hm-label"></span>`;
  }).join('');
  const total = Object.values(durationByDay).reduce((a,b)=>a+b,0);
  const active = Object.values(durationByDay).filter(v=>v>0).length;
  const avg = active ? total / active : 0;
  host.innerHTML = `
    <div class="hm-labels">${monthLabels}</div>
    <div class="heatmap">${weeks.join('')}</div>
    <div class="hm-legend">
      <span>Less</span>
      ${shades.map(s=>`<span class="sw" style="background:${s.c}"></span>`).join('')}
      <span>More</span>
      <span style="margin-left:12px">${active} active days · ${Math.round(total)} min total · avg ${avg.toFixed(0)} min on active days</span>
    </div>`;
}

